declare
  doc jsonb := $seed${"id":"budget-2027","type":"Хуулийн төсөл","stage":"Хэлэлцэх эсэх","topics":["Төсөв ба санхүү","Боловсрол","Эрүүл мэнд","Орон сууц"],"featured":true,"order":2,"title":"2027 оны төсвийн төсөл: зарлага 43.6 их наяд, алдагдал 2.3 их наяд төгрөг","officialTitle":{"text":"Монгол Улсын 2027 оны төсвийн тухай, Үндэсний баялгийн сангийн 2027 оны төсвийн тухай, Нийгмийн даатгалын сангийн 2027 оны төсвийн тухай, Эрүүл мэндийн даатгалын сангийн 2027 оны төсвийн тухай хуулийн төслүүд, Монгол Улсын нэгдсэн төсвийн 2027 оны төсвийн хүрээний мэдэгдэл, 2028–2029 оны төсвийн төсөөллийн тухай хуульд өөрчлөлт оруулах тухай хуулийн төсөл","source":"ikon-budget","verify":"Төсөл тус бүрийн албан ёсны нэрийг d.parliament.mn-ээс тулгах"},"summary":{"text":"Засгийн газар 2026 оны 8-р сарын 31-нд УИХ-д өргөн мэдүүлсэн 2027 оны төсвийн төслөөр тэнцвэржүүлсэн орлого 41.3 их наяд, зарлага 43.6 их наяд, алдагдал 2.306 их наяд төгрөг байна.","source":"gogo-budget"},"publishedAt":"2026-09-25","reviewed":{"by":"TODO_VERIFY","date":"TODO_VERIFY"},"timeline":[{"date":"2026-08-31","label":"Ерөнхий сайд төсвийн төслөөс онцлох есөн шийдвэрийг танилцуулсан","status":"done","source":"gov-9-decisions"},{"date":"2026-08-31","label":"УИХ-д өргөн мэдүүлсэн","note":"Ерөнхий сайд, Сангийн сайд УИХ-ын даргад өргөн барьсан","status":"done","source":"gogo-budget"},{"date":"2026-09-15","label":"Чуулганы нэгдсэн хуралдаанд хэлэлцэхээр оруулсан","note":"АН-ын бүлэг ажлын гурван өдрийн завсарлага авсан","status":"current","source":"ikon-budget","verify":"Эх мэдээнд хэлэлцүүлгийн шатыг бичээгүй. 2026.09.24-нд d.parliament.mn, parliament.mn-ээс шатыг шалгаж, stage болон энэ мөрийг шинэчлэх"},{"date":null,"label":"Анхны хэлэлцүүлэг","status":"upcoming"},{"date":null,"label":"Эцсийн хэлэлцүүлэг","status":"upcoming"},{"date":null,"label":"Эцэслэн батлах","status":"upcoming"}],"keyNumbers":[{"label":"Нийт орлого","value":"45.7 их наяд төгрөг","source":"arslan-budget"},{"label":"Тэнцвэржүүлсэн орлого","value":"41.3 их наяд төгрөг","source":"arslan-budget"},{"label":"Нийт зарлага","value":"43.6 их наяд төгрөг","note":"ДНБ-ий 37.3%","source":"arslan-budget","verify":"Төсвийн тогтвортой байдлын зөвлөлийн дүгнэлтийг мэдээлсэн ikon.mn/n/3qcr-д өргөн мэдүүлсэн төслийн зарлагыг ДНБ-ий 37.8% гэжээ. Албан танилцуулгаас тулгаж, зөрвөл note-ийг засах эсвэл хасах"},{"label":"Тэнцвэржүүлсэн тэнцэл","value":"−2.306 их наяд төгрөг","note":"Алдагдал","source":"ikon-budget"}],"numberExplainer":{"question":"Орлого 45.7 үү, 41.3 их наяд төгрөг үү?","paragraphs":[{"text":"Хоёулаа зөв, гэхдээ өөр үзүүлэлт: 45.7 их наяд төгрөг нь нэгдсэн төсвийн нийт орлого, 41.3 их наяд төгрөг нь тэнцвэржүүлсэн орлого.","source":"arslan-budget"},{"text":"Төсвийн тэнцлийг тэнцвэржүүлсэн орлогоос тооцдог: 41.3 − 43.6 ≈ −2.3 их наяд төгрөгийн алдагдал.","source":"ikon-budget"},{"text":"Хуулиар тэнцвэржүүлсэн орлого гэдэг нь гол нэр төрлийн эрдэс баялгийн орлогыг хуульд заасан үнийн түвшнээр тооцож, бусад орлоготой нэмээд, тухайн жилд Ирээдүйн өв санд хуримтлагдах орлогыг хассан дүн юм.","source":"legalinfo-fiscal-stability","verify":"Claude 4.1.5-аас бичсэн — хүн тулгаж шалгах"}]},"meaning":[{"text":"Тэнцвэржүүлсэн орлого зарлагаас бага тул төсөв 2.306 их наяд төгрөгийн алдагдалтай байхаар төлөвлөгджээ.","source":"ikon-budget"},{"text":"Төслөөр тэтгэвэр, тэтгэмжийг 10%, төрийн албан хаагчдын цалинг 10–20% нэмэхээр төлөвлөжээ.","source":"arslan-budget"}],"positions":[{"actor":"Засгийн газар","text":"Хувь хүний орлогын албан татвар, нийгмийн даатгалын хуулийн өөрчлөлтөөр тэнцвэржүүлсэн орлого батлагдсан дүнгээс 1 их наяд төгрөгөөр дутах тул төсвийн үзүүлэлтүүдийг шинэчлэн тооцох шаардлагатай гэж тайлбарласан.","source":"ikon-fiscal-council"},{"actor":"УИХ дахь АН-ын бүлэг","text":"Төсвийн зарлагыг 43.6 их наяд төгрөгт хүргэсэн асуудлыг хууль зөрчсөн гэж үзэж, УИХ-аар хэлэлцэхгүй байх ёстой гэж мэдэгдсэн.","source":"ikon-budget"}],"affects":[{"group":"Тэтгэвэр авагч","text":"Тэтгэвэр, тэтгэмжийг үнийн өсөлттэй уялдуулан 10% нэмэхээр төлөвлөжээ.","source":"arslan-budget"},{"group":"Төрийн албан хаагч","text":"Төрийн үйлчилгээний албан хаагчийн цалин 2027 оны II улирлаас 10%, төрийн захиргааны болон тусгай албан хаагчийнх 20% нэмэгдэхээр төлөвлөжээ.","source":"arslan-budget"},{"group":"Ажилтан","text":"Сарын 792,000₮ хүртэлх цалин татвараас чөлөөлөгдсөнөөр иргэдийн татварын ачаалал 840 тэрбум төгрөгөөр буурна гэж тооцжээ.","source":"arslan-budget"},{"group":"Эцэг эх","text":"2027 онд боловсролын салбарын 356 төсөл, арга хэмжээг 1.4 их наяд төгрөгөөр санхүүжүүлэхээр тусгажээ. Үүнд 132 сургууль, 69 цэцэрлэг барих ажил багтана.","source":"arslan-budget"},{"group":"Иргэн","text":"Даралт, зүрх судас, чихрийн шижингийн эмийг эрүүл мэндийн даатгалын сангаас 100% хөнгөлж, иргэдийн 79 тэрбум төгрөгийг хэмнэхээр тусгажээ.","source":"arslan-budget"},{"group":"Иргэн","text":"16 мянга орчим иргэнийг орон сууцтай болгох зорилт тусгажээ.","source":"arslan-budget"},{"group":"Бизнес эрхлэгч","text":"Аж ахуйн нэгжийн татварын ачаалал 246 тэрбум төгрөгөөр буурч, нийгмийн даатгалын шимтгэлд 186.3 тэрбум төгрөгийн хөнгөлөлт үзүүлэхээр тусгажээ.","source":"arslan-budget"}],"evidence":[{"step":"Бодлого","items":[{"text":"Засгийн газар 2026 оны 8-р сарын 31-нд төсвийн төслөөс онцлох есөн шийдвэрээ танилцуулсан.","source":"gov-9-decisions"},{"text":"Засгийн газар 2027 оны төсвийн гол зорилгыг Монголын баялгийг монголчууддаа хүргэх гэж тодорхойлсон.","source":"gov-9-decisions"}]},{"step":"Төсөв","items":[{"text":"Нийт зарлага 43.6 их наяд төгрөг, тэнцвэржүүлсэн тэнцэл 2.306 их наяд төгрөгийн алдагдалтай.","source":"ikon-budget"}]},{"step":"Үр нөлөөний үнэлгээ","items":[{"text":"Төсвийн тогтвортой байдлын зөвлөл төрийн албан хаагчдын цалингийн хэт өсөлт хувийн хэвшилд дарамт болох хандлагатай гэж дүгнэжээ.","source":"ubn-fiscal-council","verify":"Зөвлөлийн дүгнэлтийн бүтэн эхийг уншиж баталгаажуулах"}]},{"step":"Олон нийтийн санал","items":[{"text":"Эдийн засаг, хөгжлийн яам Төсвийн тухай хуулийн 